  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'COPY-HOUR', qty: 3 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
